// Render a graph generated by the C# compiler with the actual Faust WASM runtime.
// CI exports the probe and compiles its source before running this test.
import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const directory = process.env.ORBIT_GRAPH_PROBE_DIR;
assert.ok(directory, "Set ORBIT_GRAPH_PROBE_DIR to the exported and compiled graph probe");
const compiled = join(directory, "compiled");
const { FaustMonoDspGenerator } = await import(pathToFileURL(join(compiled, "faustwasm/index.js")));
const module = await WebAssembly.compile(await readFile(join(compiled, "dsp-module.wasm")));
const json = await readFile(join(compiled, "dsp-meta.json"), "utf8");
const manifest = JSON.parse(await readFile(join(directory, "controls.json"), "utf8"));

function estimateFrequency(samples, rate, start, end) {
    const positions = [];
    for (let index = Math.floor(start * rate); index < Math.floor(end * rate); index++) {
        if (samples[index - 1] <= 0 && samples[index] > 0)
            positions.push(index - 1 - samples[index - 1] / (samples[index] - samples[index - 1]));
    }
    assert.ok(positions.length > 2);
    return (positions.length - 1) * rate / (positions.at(-1) - positions[0]);
}

function peak(samples, rate, start, end) {
    let maximum = 0;
    for (let index = Math.floor(start * rate); index < Math.floor(end * rate); index++)
        maximum = Math.max(maximum, Math.abs(samples[index]));
    return maximum;
}

async function render(rate, overrides = {}) {
    const processor = await new FaustMonoDspGenerator().createOfflineProcessor(
        rate, 128, { module, json, soundfiles: {} });
    assert.ok(processor);
    for (const [name, value] of Object.entries({ ...manifest.values, ...overrides })) {
        const path = processor.getParams().find(candidate => candidate.endsWith("/" + name));
        assert.ok(path, "Missing generated parameter " + name);
        processor.setParamValue(path, value);
    }
    const [samples] = processor.render([], rate * 4);
    return samples;
}

for (const rate of [44100, 48000]) {
    test("generated graph renders pitch and gain modulation at " + rate + " Hz", async () => {
        const samples = await render(rate);
        assert.equal(samples.length, rate * 4);
        let previous = 0;
        for (const sample of samples) {
            assert.ok(Number.isFinite(sample));
            assert.ok(Math.abs(sample) <= 0.151);
            assert.ok(Math.abs(sample - previous) < 0.05, "Discontinuous waveform");
            previous = sample;
        }
        const frequencies = [];
        const peaks = [];
        for (let time = 1; time < 3.8; time += 0.1) {
            frequencies.push(estimateFrequency(samples, rate, time, time + 0.1));
            peaks.push(peak(samples, rate, time, time + 0.1));
        }
        assert.ok(Math.min(...frequencies) > 330 && Math.min(...frequencies) < 360);
        assert.ok(Math.max(...frequencies) > 520 && Math.max(...frequencies) < 550);
        assert.ok(Math.min(...peaks) < 0.065);
        assert.ok(Math.max(...peaks) > 0.135);
    });

    test("host can override the generated frequency control at " + rate + " Hz", async () => {
        const samples = await render(rate, { [manifest.frequency]: 220 });
        const frequencies = [];
        for (let time = 1; time < 3.8; time += 0.1)
            frequencies.push(estimateFrequency(samples, rate, time, time + 0.1));
        assert.ok(Math.min(...frequencies) > 110 && Math.min(...frequencies) < 140);
        assert.ok(Math.max(...frequencies) > 300 && Math.max(...frequencies) < 330);
    });
}
